/* Skin "modern-minimal" (Modern Minimal): the tweakcn preset "modern-minimal" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="modern-minimal" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Inter (Google Fonts, loaded when the skin is on). */
[data-skin="modern-minimal"] {
  --background: hsl(0 0% 100%);
  --foreground: hsl(0 0% 20%);
  --card: hsl(0 0% 100%);
  --card-foreground: hsl(0 0% 20%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(0 0% 20%);
  --primary: hsl(217.3 76.8% 52.7%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(220 14% 96%);
  --secondary-foreground: hsl(215 14% 34%);
  --muted: hsl(210 20% 98%);
  --muted-foreground: hsl(220 9% 46%);
  --accent: hsl(204 94% 94%);
  --accent-foreground: hsl(224.4 64.3% 32.9%);
  --destructive: hsl(358.3 71.8% 52.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(220 13% 91%);
  --input: hsl(220 13% 91%);
  --ring: hsl(217.2 91.2% 59.8%);
  --chart-1: hsl(217.2 91.2% 59.8%);
  --chart-2: hsl(221 83% 53%);
  --chart-3: hsl(224.3 76.3% 48%);
  --chart-4: hsl(226 71% 40%);
  --chart-5: hsl(224.4 64.3% 32.9%);
  --sidebar: hsl(210 20% 98%);
  --sidebar-foreground: hsl(0 0% 20%);
  --sidebar-primary: hsl(217.2 91.2% 59.8%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(204 94% 94%);
  --sidebar-accent-foreground: hsl(224.4 64.3% 32.9%);
  --sidebar-border: hsl(220 13% 91%);
  --sidebar-ring: hsl(217.2 91.2% 59.8%);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --radius: 0.375rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(358.3 71.8% 46.7%);
}

:is(.dark, [data-theme="dark"]) [data-skin="modern-minimal"],
[data-skin="modern-minimal"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(0 0% 9%);
  --foreground: hsl(0 0% 90%);
  --card: hsl(0 0% 15%);
  --card-foreground: hsl(0 0% 90%);
  --popover: hsl(0 0% 15%);
  --popover-foreground: hsl(0 0% 90%);
  --primary: hsl(217.3 76.8% 52.7%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(0 0% 15%);
  --secondary-foreground: hsl(0 0% 90%);
  --muted: hsl(0 0% 12%);
  --muted-foreground: hsl(0 0% 64%);
  --accent: hsl(224.4 64.3% 32.9%);
  --accent-foreground: hsl(213 97% 87%);
  --destructive: hsl(358.3 71.8% 52.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(0 0% 25%);
  --input: hsl(0 0% 25%);
  --ring: hsl(217.2 91.2% 59.8%);
  --chart-1: hsl(213 94% 68%);
  --chart-2: hsl(217.2 91.2% 59.8%);
  --chart-3: hsl(221 83% 53%);
  --chart-4: hsl(224.3 76.3% 48%);
  --chart-5: hsl(226 71% 40%);
  --sidebar: hsl(0 0% 9%);
  --sidebar-foreground: hsl(0 0% 90%);
  --sidebar-primary: hsl(217.2 91.2% 59.8%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(224.4 64.3% 32.9%);
  --sidebar-accent-foreground: hsl(213 97% 87%);
  --sidebar-border: hsl(0 0% 25%);
  --sidebar-ring: hsl(217.2 91.2% 59.8%);
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(358.3 71.8% 46.7%);
}

[data-skin="modern-minimal"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="modern-minimal"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="modern-minimal"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="modern-minimal"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="modern-minimal"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="modern-minimal"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
